from itertools import combinations

# Vertices 0-5
vertices = list(range(6))
all_edges = list(combinations(vertices, 2))

# We need to find a maximal triangle-free graph
# Triangle-free: no three vertices all connected
# Maximal: for every non-edge (u,v), adding it would create a triangle
#          i.e., there exists w such that (u,w) and (v,w) are both edges

# Fixed: edge (3,5) must be present

def is_triangle_free(edges_set):
    """Check if the graph has no triangles."""
    for i, j, k in combinations(vertices, 3):
        if (i,j) in edges_set and (j,k) in edges_set and (i,k) in edges_set:
            return False
    return True

def is_maximal(edges_set):
    """Check if adding any non-edge would create a triangle."""
    non_edges = [e for e in all_edges if e not in edges_set]
    for u, v in non_edges:
        # Check if adding (u,v) would create a triangle
        # It would create a triangle if there exists w such that (u,w) and (v,w) are in edges_set
        would_create_triangle = False
        for w in vertices:
            if w != u and w != v:
                edge_uw = (min(u,w), max(u,w))
                edge_vw = (min(v,w), max(v,w))
                if edge_uw in edges_set and edge_vw in edges_set:
                    would_create_triangle = True
                    break
        if not would_create_triangle:
            return False  # Not maximal, we could add (u,v)
    return True

# Try all possible subsets of edges that include (3,5)
fixed_edge = (3, 5)
other_edges = [e for e in all_edges if e != fixed_edge]

best_solution = None
best_num_edges = 0

# Try all 2^14 subsets
for mask in range(2**len(other_edges)):
    edges_set = {fixed_edge}
    for i, e in enumerate(other_edges):
        if mask & (1 << i):
            edges_set.add(e)

    if is_triangle_free(edges_set) and is_maximal(edges_set):
        if len(edges_set) > best_num_edges:
            best_num_edges = len(edges_set)
            best_solution = edges_set

if best_solution:
    print(f"Found maximal triangle-free graph with {best_num_edges} edges:")
    print(sorted(best_solution))
else:
    print("No solution found")
